255	1023      static private List<Set<FType>> overlapPieces(FType p, FType q, Set<List<FType>> path, int[] steps) {
256	1024          if (--steps[0] < 0) return null;
257	1025          if (p instanceof SymbolicType || q instanceof SymbolicType) return null;
258	1026          List<Set<FType>> res = new ArrayList<Set<FType>>();
259	1027          try {
260	1028              if (p.subtypeOf(q)) {
261	1029                  res.add(Collections.singleton(p));
262	1030                  return res;
263	1031              }
264	1032              if (q.subtypeOf(p)) {
265	1033                  res.add(Collections.singleton(q));
266	1034                  return res;
267	1035              }
268	1036              if (p.excludesOther(q)) return res;
269	1037              Set<FType> pc = p.getComprises();
270	1038              Set<FType> qc = q.getComprises();
271	1039              if (pc == null && qc == null) {
272	1040                  Set<FType> both = new HashSet<FType>();
273	1041                  both.add(p);
274	1042                  both.add(q);
275	1043                  res.add(both);
276	1044                  return res;
277	1045              }
278	1046              List<FType> key = Useful.<FType>list(p, q);
279	1047              if (!path.add(key)) return null;
280	1048              if (pc != null) {
281	1049                  for (FType c : pc) {
282	1050                      List<Set<FType>> sub = overlapPieces(c, q, path, steps);
283	1051                      if (sub == null) return null;
284	1052                      res.addAll(sub);
285	1053                  }
286	1054              } else {
287	1055                  for (FType c : qc) {
288	1056                      List<Set<FType>> sub = overlapPieces(p, c, path, steps);
289	1057                      if (sub == null) return null;
290	1058                      res.addAll(sub);
291	1059                  }
292	1060              }
293	1061              path.remove(key);
294	1062              return res;
295	1063          }
296	1064          catch (FortressException ex) {
297	1065              return null;
