static private final class Provided {
    final FnDecl decl;
    final String name;
    final int self;
    final FTraitOrObject type;
    final List<FType> params;

    Provided(FnDecl decl, int self, FTraitOrObject type) {
        this.decl = decl;
        this.name = NodeUtil.nameString(NodeUtil.getName(decl));
        this.self = self;
        this.type = type;
